-- Phase 5G expand: Legacy Permission Mapping Burn-down and Entry Point Authority Inventory.
-- PostgreSQL remains the single runtime authority; this migration publishes Catalog Revision 5.

-- Flyway runs each migration in its own transaction. Set an explicit INSTANCE
-- authority context before accessing FORCE-RLS protected global RBAC rows.
select set_config('app.current_tenant_id','INSTANCE',true);
select set_config('app.current_actor_id','phase5g-migration',true);

insert into permission_catalog_revisions(
  revision_id,revision_code,revision_number,status,content_hash,description,supersedes_revision_id,
  created_at,created_by,published_at,published_by,version)
select '00000000-0000-0000-0000-000000000005'::uuid,'PHASE5G-0.8.2',
       coalesce(max(revision_number),0)+1,'DRAFT','DRAFT:UNPUBLISHED',
       'Phase 5G Entry Point Authority Inventory, Legacy Mapping and Bypass governance permissions.',
       (select revision_id from permission_catalog_active_revision where singleton_id='ACTIVE'),
       now(),'phase5g-migration',null,null,1
from permission_catalog_revisions
on conflict(revision_id) do nothing;

insert into permission_catalog_revision_entries(
  revision_id,permission_code,owner_module,resource_type,action_code,description,risk_level,risk_lane,
  lifecycle,allowed_scope_types,system_managed,replacement_permission_code,introduced_at,deprecated_at,
  retired_at,updated_at,updated_by,version)
select '00000000-0000-0000-0000-000000000005'::uuid,e.permission_code,e.owner_module,e.resource_type,
       e.action_code,e.description,e.risk_level,e.risk_lane,e.lifecycle,e.allowed_scope_types,e.system_managed,
       e.replacement_permission_code,e.introduced_at,e.deprecated_at,e.retired_at,now(),'phase5g-migration',1
from permission_catalog_revision_entries e
join permission_catalog_active_revision a on a.singleton_id='ACTIVE' and a.revision_id=e.revision_id
on conflict(revision_id,permission_code) do nothing;

insert into permission_catalog_revision_aliases(
  revision_id,alias_code,canonical_permission_code,alias_type,valid_from,valid_until,reason,created_by,created_at,version)
select '00000000-0000-0000-0000-000000000005'::uuid,a.alias_code,a.canonical_permission_code,
       a.alias_type,a.valid_from,a.valid_until,a.reason,'phase5g-migration',now(),1
from permission_catalog_revision_aliases a
join permission_catalog_active_revision active on active.singleton_id='ACTIVE' and active.revision_id=a.revision_id
on conflict(revision_id,alias_code) do nothing;

insert into permission_catalog_revision_entries(
  revision_id,permission_code,owner_module,resource_type,action_code,description,risk_level,risk_lane,
  lifecycle,allowed_scope_types,system_managed,replacement_permission_code,introduced_at,deprecated_at,
  retired_at,updated_at,updated_by,version)
values
 ('00000000-0000-0000-0000-000000000005','permission.entry_point.read','permission-readiness','ENTRY_POINT','READ','Read the global Entry Point Authority Inventory and burn-down evidence.','HIGH','READ','ACTIVE',array['INSTANCE'],true,null,now(),null,null,now(),'phase5g-migration',1),
 ('00000000-0000-0000-0000-000000000005','permission.entry_point.manage','permission-readiness','ENTRY_POINT','MANAGE','Update Entry Point owner, authority state, target Permission, resolver and migration deadline.','CRITICAL','CRITICAL','ACTIVE',array['INSTANCE'],true,null,now(),null,null,now(),'phase5g-migration',1),
 ('00000000-0000-0000-0000-000000000005','permission.legacy_mapping.manage','permission-readiness','LEGACY_AUTHORITY_MAPPING','MANAGE','Map a legacy role or authority to the canonical PostgreSQL Permission Catalog.','CRITICAL','ADMIN','ACTIVE',array['INSTANCE'],true,null,now(),null,null,now(),'phase5g-migration',1),
 ('00000000-0000-0000-0000-000000000005','permission.bypass.manage','permission-readiness','ENTRY_POINT_BYPASS','MANAGE','Create, expire or revoke a time-bounded Entry Point compatibility bypass.','CRITICAL','CRITICAL','ACTIVE',array['INSTANCE'],true,null,now(),null,null,now(),'phase5g-migration',1)
on conflict(revision_id,permission_code) do update set owner_module=excluded.owner_module,resource_type=excluded.resource_type,
 action_code=excluded.action_code,description=excluded.description,risk_level=excluded.risk_level,risk_lane=excluded.risk_lane,
 lifecycle='ACTIVE',allowed_scope_types=excluded.allowed_scope_types,updated_at=excluded.updated_at,updated_by=excluded.updated_by,
 version=permission_catalog_revision_entries.version+1;

select set_config('app.permission_catalog_publish_revision_id','00000000-0000-0000-0000-000000000005',true);
insert into permission_definitions(permission_code,resource_type,action_code,description,risk_level,allowed_scope_types,system_managed,
 active,version,owner_module,risk_lane,lifecycle,catalog_revision_id,replacement_permission_code,introduced_at,deprecated_at,retired_at,updated_at,updated_by)
select permission_code,resource_type,action_code,description,risk_level,allowed_scope_types,system_managed,lifecycle<>'RETIRED',1,
 owner_module,risk_lane,lifecycle,revision_id,replacement_permission_code,introduced_at,deprecated_at,retired_at,updated_at,updated_by
from permission_catalog_revision_entries where revision_id='00000000-0000-0000-0000-000000000005'::uuid
on conflict(permission_code) do update set resource_type=excluded.resource_type,action_code=excluded.action_code,description=excluded.description,
 risk_level=excluded.risk_level,allowed_scope_types=excluded.allowed_scope_types,system_managed=excluded.system_managed,active=excluded.active,
 owner_module=excluded.owner_module,risk_lane=excluded.risk_lane,lifecycle=excluded.lifecycle,catalog_revision_id=excluded.catalog_revision_id,
 replacement_permission_code=excluded.replacement_permission_code,deprecated_at=excluded.deprecated_at,retired_at=excluded.retired_at,
 updated_at=excluded.updated_at,updated_by=excluded.updated_by,version=permission_definitions.version+1;
update permission_catalog_revisions set status='SUPERSEDED',version=version+1
where revision_id=(select revision_id from permission_catalog_active_revision where singleton_id='ACTIVE')
  and revision_id<>'00000000-0000-0000-0000-000000000005'::uuid and status='PUBLISHED';
update permission_catalog_revisions set status='PUBLISHED',content_hash=(
 with catalog_lines as (
  select 'P|'||permission_code||'|'||owner_module||'|'||resource_type||'|'||action_code||'|'||description||'|'||risk_level||'|'||risk_lane||'|'||lifecycle||'|'||coalesce(array_to_string(allowed_scope_types,','),'')||'|'||system_managed::text||'|'||coalesce(replacement_permission_code,'') line
  from permission_catalog_revision_entries where revision_id='00000000-0000-0000-0000-000000000005'::uuid
  union all select 'A|'||alias_code||'|'||canonical_permission_code||'|'||alias_type||'|'||coalesce(to_char(valid_from at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'')||'|'||coalesce(to_char(valid_until at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'')||'|'||reason
  from permission_catalog_revision_aliases where revision_id='00000000-0000-0000-0000-000000000005'::uuid)
 select 'sha256:'||encode(sha256(convert_to(coalesce(string_agg(line,E'\n' order by line),''),'UTF8')),'hex') from catalog_lines),
 published_at=now(),published_by='phase5g-migration',version=version+1
where revision_id='00000000-0000-0000-0000-000000000005'::uuid and status='DRAFT';
update permission_catalog_active_revision set revision_id='00000000-0000-0000-0000-000000000005'::uuid,activated_at=now(),activated_by='phase5g-migration',version=version+1 where singleton_id='ACTIVE';
insert into permission_catalog_publication_events(publication_id,revision_id,previous_revision_id,content_hash,entry_count,alias_count,actor_id,audit_reason,correlation_id,published_at)
select '00000000-0000-0000-0000-000000005005'::uuid,r.revision_id,r.supersedes_revision_id,r.content_hash,
 (select count(*)::integer from permission_catalog_revision_entries e where e.revision_id=r.revision_id),
 (select count(*)::integer from permission_catalog_revision_aliases a where a.revision_id=r.revision_id),
 'phase5g-migration','Phase 5G migration-owned Catalog publication','phase5g-migration',coalesce(r.published_at,now())
from permission_catalog_revisions r where r.revision_id='00000000-0000-0000-0000-000000000005'::uuid on conflict(publication_id) do nothing;

insert into rbac_role_permissions(grant_id,tenant_id,role_id,permission_point,created_at,created_by,version) values
 ('grant-system-admin-entry-point-read',null,'role-system-admin','permission.entry_point.read',now(),'phase5g-migration',1),
 ('grant-system-admin-entry-point-manage',null,'role-system-admin','permission.entry_point.manage',now(),'phase5g-migration',1),
 ('grant-system-admin-legacy-mapping-manage',null,'role-system-admin','permission.legacy_mapping.manage',now(),'phase5g-migration',1),
 ('grant-system-admin-bypass-manage',null,'role-system-admin','permission.bypass.manage',now(),'phase5g-migration',1),
 ('grant-auditor-entry-point-read',null,'role-auditor','permission.entry_point.read',now(),'phase5g-migration',1)
on conflict(role_id,permission_point) do nothing;

create table if not exists permission_entry_point_inventory(
 entry_point_id varchar(240) primary key,entry_point_type varchar(32) not null,application_id varchar(128) not null,
 owner_module varchar(128) not null,display_name varchar(240) not null,route_pattern varchar(500),http_method varchar(16),
 authority_state varchar(32) not null,target_permission_code varchar(160),legacy_authority_type varchar(64),
 legacy_authorities jsonb not null default '[]'::jsonb,resource_type varchar(96) not null,resource_resolver_id varchar(200) not null,
 exemption_reason varchar(1000),migration_deadline date,manifest_revision varchar(128) not null,source_ref varchar(1000) not null,
 source_hash varchar(64) not null,last_verified_at timestamptz not null default now(),created_at timestamptz not null default now(),
 created_by varchar(128) not null default 'phase5g-migration',updated_at timestamptz not null default now(),
 updated_by varchar(128) not null default 'phase5g-migration',version bigint not null default 1
);
create index if not exists idx_permission_entry_point_state on permission_entry_point_inventory(authority_state,owner_module);
create index if not exists idx_permission_entry_point_permission on permission_entry_point_inventory(target_permission_code);

create table if not exists permission_legacy_authority_mappings(
 mapping_id varchar(128) primary key,legacy_authority_type varchar(64) not null,legacy_authority_code varchar(500) not null,
 target_permission_code varchar(160),owner_module varchar(128) not null,status varchar(32) not null,migration_deadline date,
 notes varchar(1000) not null default '',created_by varchar(128) not null,created_at timestamptz not null default now(),
 updated_by varchar(128) not null default 'phase5g-migration',updated_at timestamptz not null default now(),version bigint not null default 1,
 unique(legacy_authority_type,legacy_authority_code)
);
create table if not exists permission_entry_point_bypasses(
 bypass_id varchar(128) primary key,entry_point_id varchar(240) not null references permission_entry_point_inventory(entry_point_id),
 owner_id varchar(128) not null,reason varchar(1000) not null,replacement varchar(500) not null,expires_at timestamptz not null,
 status varchar(32) not null default 'ACTIVE',created_by varchar(128) not null,created_at timestamptz not null default now(),
 revoked_by varchar(128),revoked_at timestamptz,revoke_reason varchar(1000),version bigint not null default 1
);
create index if not exists idx_permission_entry_point_bypass_active on permission_entry_point_bypasses(entry_point_id,expires_at) where status='ACTIVE';
create table if not exists permission_entry_point_events(
 event_id uuid primary key,event_type varchar(64) not null,aggregate_type varchar(64) not null,aggregate_id varchar(240) not null,
 previous_json jsonb not null default '{}'::jsonb,current_json jsonb not null default '{}'::jsonb,audit_reason varchar(500) not null,
 actor_id varchar(128) not null,correlation_id varchar(128),occurred_at timestamptz not null default now()
);

