create or replace view permission_entry_point_readiness with (security_invoker=true) as
select i.*,
 case when i.target_permission_code is not null and p.permission_code is null then true else false end as unknown_permission,
 case when i.authority_state in('LEGACY_ONLY','DUAL_SHADOW') and i.target_permission_code is null
       and not exists(select 1 from permission_legacy_authority_mappings m where m.status='MAPPED' and m.legacy_authority_code in(select jsonb_array_elements_text(i.legacy_authorities))) then true else false end as missing_mapping,
 case when i.authority_state in('TARGET_READY','TARGET_ONLY','DUAL_SHADOW') and i.resource_resolver_id in('','NONE') and i.resource_type not in('IDENTITY','SECURITY','AUDIT','INSTANCE','PERMISSION','GLOBAL') then true else false end as missing_resolver,
 case when i.migration_deadline is not null and i.migration_deadline<current_date and i.authority_state not in('TARGET_ONLY','EXEMPT') then true else false end as overdue,
 exists(select 1 from permission_entry_point_bypasses b where b.entry_point_id=i.entry_point_id and b.status='ACTIVE' and b.expires_at>now()) as active_bypass,
 exists(select 1 from permission_entry_point_bypasses b where b.entry_point_id=i.entry_point_id and b.status='ACTIVE' and b.expires_at<=now()) as expired_bypass
from permission_entry_point_inventory i left join permission_definitions p on p.permission_code=i.target_permission_code and p.active=true and p.lifecycle in('ACTIVE','DEPRECATED');
